exec(open('tools/common.py').read())
# Intermediate unit 26 – Change. Bám sách: trang 56–57 (đã xem ảnh trang) + đáp án + Mini dictionary. Không chép nguyên văn.
# look up (u1), changeover (u4), get over (u17) đã có thẻ → chỉ nhắc. stick with sth (giữ như kế hoạch) khác stick with it (kiên trì – u19).
theory = (
 H("A", "Up meaning more or better", "Up nghĩa là nhiều hơn, tốt hơn")
 + P("With verbs of change, <i>up</i> often adds the idea of becoming more or better: the number of students with good marks is <b>going up</b> (increasing); a lecture room is <b>filling up</b> (getting fuller); the situation is <b>looking up</b> (improving – card in Unit 1); business is <b>picking up</b> after a bad start to the year; you can <b>heat up</b> rice (make it warmer); it’s time Simon <b>woke up to</b> what’s happening (became aware of it).",
     "Với các động từ chỉ thay đổi, <i>up</i> thường thêm ý ‘nhiều hơn, tốt hơn’: số học sinh điểm cao đang <b>going up</b> (tăng); giảng đường đang <b>filling up</b> (đông dần); tình hình đang <b>looking up</b> (khá lên – đã có thẻ ở bài 1); việc kinh doanh <b>picking up</b> sau đầu năm ảm đạm; có thể <b>heat up</b> cơm (hâm nóng); đã đến lúc Simon <b>woke up to</b> chuyện đang diễn ra (nhận ra).")
 + H("B", "Other phrasal verbs relating to change", "Các phrasal verb khác về thay đổi")
 + P("Looking back over a year: at work there was an almost total <b>changeover</b> of staff (card in Unit 4); the office <b>phased out</b> its old computers (gradually stopped using them) and <b>phased in</b> a new administration system (gradually started using it); the writer wasn’t sure how things would <b>pan out</b> (develop), but the arguments soon <b>blew over</b> (became unimportant and were forgotten). Personally, it took a while to <b>get over</b> a break-up (card in Unit 17); he has <b>given up</b> caffeine (stopped an unhealthy habit); the bad effects have <b>worn off</b> (gradually disappeared) and he <b>stuck with</b> his new regime (didn’t change his plan).",
     "Nhìn lại một năm: ở chỗ làm, nhân viên gần như thay toàn bộ (<b>changeover</b> – đã có thẻ ở bài 4); văn phòng <b>phased out</b> máy tính cũ (dần thôi dùng) và <b>phased in</b> hệ thống hành chính mới (dần đưa vào dùng); người viết chưa chắc mọi việc sẽ <b>pan out</b> thế nào (diễn biến), nhưng tranh cãi sớm <b>blew over</b> (lắng xuống rồi bị quên). Về chuyện riêng, mất một thời gian mới <b>get over</b> chuyện chia tay (đã có thẻ ở bài 17); anh đã <b>given up</b> caffeine (bỏ thói quen không lành mạnh); cảm giác khó chịu đã <b>worn off</b> (dần biến mất) và anh <b>stuck with</b> chế độ mới (giữ đúng kế hoạch).")
 + NOTE("<b>Tip</b>: learn some phrasal verbs in pairs of opposites – <i>phase in / phase out</i> a system, <i>heat up / cool down</i> food, <i>take up / give up</i> an activity, prices <i>go up / go down</i>.",
        "<b>Mẹo</b>: học một số phrasal verb theo cặp trái nghĩa – <i>phase in / phase out</i> hệ thống, <i>heat up / cool down</i> đồ ăn, <i>take up / give up</i> một hoạt động, giá <i>go up / go down</i>.")
)
